 $policy=ok_api('create-request',['kind'=>'retention_policy','reason'=>'Isolated lifecycle test; retains all current records','payload'=>['trip_location_days'=>3650,'closed_case_days'=>3650,'deleted_document_days'=>3650,'session_days'=>3650,'legal_basis'=>'Test aged fixtures only','jurisdiction'=>'Local fixture','version'=>$previous['version']??0]],$compliance)['request_id'];review_policy($policy,$privacy);$journals=(int)sql('SELECT COUNT(*) FROM rs_journals')->fetchColumn();
